const $=(s)=>document.querySelector(s), $$=(s)=>[...document.querySelectorAll(s)];
async function get(name){if(window.MOFFL_DATA && Object.prototype.hasOwnProperty.call(window.MOFFL_DATA,name)) return window.MOFFL_DATA[name]; return fetch(`data/${name}.json`).then(r=>r.json())}
const pct=v=>v==null?"—":(Number(v)*100).toFixed(1)+"%";
const money=v=>v==null?"—":Number(v).toLocaleString("en-US",{style:"currency",currency:"USD",maximumFractionDigits:0});
const num=v=>v==null?"—":Number(v).toLocaleString();
function nav(){return `<div class="topbar"><div class="shell nav"><a class="brand" href="index.html">MO<span>FFL</span></a><div class="navlinks"><a href="history.html">History</a><a href="gms.html">GM Hub</a><a href="records.html">Records</a><a href="hall-of-fame.html">Hall of Fame</a><a href="drafts.html">Drafts</a><a href="financials.html">Financials</a><a href="rules.html">Constitution</a></div></div></div>`}
function foot(){return `<footer><div class="shell">MOFFL League Archive • Built from the normalized historical database • Public historical statistics begin with the 2005 season.</div></footer>`}
document.addEventListener("DOMContentLoaded",()=>{const n=$("#nav");if(n)n.innerHTML=nav();const f=$("#footer");if(f)f.innerHTML=foot()})
